/*
 * Deterministic bytes for the mock adapter.
 *
 * Real files, not empty buffers: normalization sniffs the container from the
 * bytes and probes the media, so a fixture has to survive both. The claimed
 * duration is deliberately a little off the truth, so the mismatch path is
 * exercised locally rather than discovered in production.
 */
import type { ModelDescriptor } from "../io";
import type { GenerationSpec, RawOutput } from "../types";

/** Smallest valid PNG: 1×1, opaque. */
const PNG_1X1 = Buffer.from(
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==",
  "base64",
);

/*
 * A REAL H.264 MP4: 1 second, 8fps, 32x32, black. ~1.8KB.
 *
 * Deliberately not a hand-rolled box stub. ffprobe has to be able to read a
 * duration and dimensions out of it, or local dev never exercises the probe and
 * poster path at all — which is exactly the code this whole stage exists to add.
 */
const MP4_TINY = Buffer.from(
  "",
  "base64",
);

/** A real 1-second silent MP3, for the same reason. */
const MP3_TINY = Buffer.from(
  "",
  "base64",
);

const BODY: Record<string, { bytes: Buffer; mimeType: string }> = {
  png: { bytes: PNG_1X1, mimeType: "image/png" },
  mp4: { bytes: MP4_TINY, mimeType: "video/mp4" },
  mp3: { bytes: MP3_TINY, mimeType: "audio/mpeg" },
};

/**
 * One output. `index` varies the bytes just enough that a batch is not N
 * identical checksums — otherwise the library would dedupe them into one asset.
 */
export function renderFixture(model: ModelDescriptor, spec: GenerationSpec, index: number): RawOutput {
  const container = model.io.outputs.container;
  const body = BODY[container] ?? BODY.png;
  const bytes = index === 0 ? body.bytes : Buffer.concat([body.bytes, Buffer.from([index])]);

  // Claims describe the FIXTURE, not the request: a mock that lied about its
  // dimensions would report a mismatch on every job and train people to ignore them.
  const size = FIXTURE_SIZE[model.kind] ?? undefined;
  return {
    bytes: new Uint8Array(bytes),
    claimedMimeType: body.mimeType,
    claimedDurationSeconds: claimedDuration(model, spec),
    claimedWidth: size?.width,
    claimedHeight: size?.height,
  };
}

/** The fixtures really are this long and this big; claims must match. */
export const FIXTURE_SECONDS = 1;
const FIXTURE_SIZE: Partial<Record<string, { width: number; height: number }>> = {
  image: { width: 1, height: 1 },
  video: { width: 32, height: 32 },
};

/**
 * Vendors round. Claiming exactly the file's length would let a bug in the
 * mismatch check pass unnoticed, so the mock shaves a fraction off — small
 * enough to stay inside the tolerance, which is the realistic case.
 */
function claimedDuration(model: ModelDescriptor, _spec: GenerationSpec): number | undefined {
  if (model.kind !== "video" && model.kind !== "audio") return undefined;
  return FIXTURE_SECONDS - 0.1;
}
